import subprocess
import shutil
import os

def compress_file(filepath, output_path=None):
    if not filepath or not isinstance(filepath, str):
        raise ValueError("Invalid filepath")
    if output_path is None:
        output_path = filepath + ".gz"
    if not output_path.endswith(".gz"):
        raise ValueError("Invalid output path")
    if not os.path.exists(filepath):
        raise FileNotFoundError(f"File '{filepath}' not found")

    try:
        shutil.copyfileobj(open(filepath, 'rb'), open(output_path, 'wb'))
        subprocess.run(['gzip', '-f', output_path], check=True)
        return True
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error compressing file: {e}")
    except Exception as e:
        raise RuntimeError(f"Error compressing file: {e}")
```

