import subprocess
import shutil
import gzip
import os

def compress_file(filepath, output_path=None):
    if not filepath or not isinstance(filepath, str):
        raise ValueError("Invalid filepath")
    if output_path and not isinstance(output_path, str):
        raise ValueError("Invalid output_path")
    if not os.path.exists(filepath):
        raise FileNotFoundError(f"File {filepath} not found")

    if output_path:
        output_dir = os.path.dirname(output_path)
        if output_dir and not os.path.exists(output_dir):
            os.makedirs(output_dir)

    with open(filepath, 'rb') as f_in, gzip.open(output_path or (filepath + '.gz'), 'wb') as f_out:
        shutil.copyfileobj(f_in, f_out)

    return True
