import subprocess

def find_process(process_name):
    try:
        process_output = subprocess.check_output(['ps', '-eo', 'pid,cmd'], universal_newlines=True)
        processes = process_output.split('\n')
        matching_processes = [process for process in processes[1:] if process_name in process]
        return '\n'.join(matching_processes)
    except subprocess.CalledProcessError as e:
        return f"Error searching for process: {e}"
