import shutil
import os

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str) or not isinstance(output_path, (str, type(None))):
        raise ValueError("Invalid input types. filepath must be a string, output_path must be a string or None")

    if not os.path.exists(filepath):
        raise FileNotFoundError(f"The file {filepath} does not exist")

    if output_path is None:
        output_path = filepath + ".gz"

    if os.path.exists(output_path):
        raise FileExistsError(f"The output file {output_path} already exists")

    try:
        subprocess.run(["gzip", "-c", filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        with open(output_path, "wb") as f:
            f.write(subprocess.run(["gzip", "-c", filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True).stdout)
        return True
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to compress file: {e}")
