def find_process(process_name):
    # Validate the input to prevent potential command injection
    if not isinstance(process_name, str):
        raise TypeError("Process name must be a string")
    if not process_name:
        return ""

    # Use subprocess instead of os.system for better control
    # Use shell=False to prevent shell injection
    process_output = subprocess.run(
        ["ps", "aux"], capture_output=True, text=True, shell=False
    ).stdout

    # Use regular expression to find matching processes
    import re
    matches = re.findall(r"^\s+\d+\s+\S+\s+\S+\s+\S+\s+({})\s+.*$".format(process_name), process_output, re.MULTILINE)

    # Return the matches as a string
    return "\n".join(matches)

