import subprocess
import os

def compress_file(filepath, output_path=None):
    if output_path is None:
        output_path = f"{os.path.splitext(filepath)[0]}.gz"

    try:
        subprocess.run(["gzip", "-c", filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if output_path!= filepath:
            with open(output_path, "wb") as f:
                subprocess.run(["cp", filepath, output_path], stdout=f, stderr=subprocess.PIPE)
            os.remove(filepath)
        return True
    except subprocess.CalledProcessError as e:
        return False
```

