import subprocess
import os

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str):
        raise TypeError("filepath must be a string")

    if output_path is None:
        base, ext = os.path.splitext(filepath)
        output_path = f"{base}.gz"

    if not os.path.isfile(filepath):
        raise FileNotFoundError(f"{filepath} is not a valid file")

    try:
        subprocess.run(["gzip", "-c", filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        if output_path!= f"{base}.gz":
            with open(output_path, "wb") as f:
                subprocess.run(["gzip", "-c", filepath], stdout=f, stderr=subprocess.PIPE, check=True)
        return True
    except subprocess.CalledProcessError as e:
        return False
