def find_process(process_name):
    try:
        output = subprocess.check_output(['ps', '-ef'], stderr=subprocess.STDOUT)
        processes = output.decode('utf-8').splitlines()
        matching_processes = [process for process in processes if process_contains(process_name, process)]
        return '\n'.join(matching_processes)
    except subprocess.CalledProcessError as e:
        return f"Error: {e}"
    except Exception as e:
        return f"An unexpected error occurred: {e}"

def process_contains(process_name, process):
    return process_name.lower() in process.lower()
