import subprocess
import platform

def ping_host(hostname, count=4):
    if not isinstance(hostname, str):
        raise TypeError("Hostname must be a string")

    if not hostname:
        raise ValueError("Hostname cannot be empty")

    if not hostname.isalnum() and not hostname.replace('.', '').replace('_', '').isalnum():
        raise ValueError("Hostname can only contain alphanumeric characters, dots, and underscores")

    if platform.system()!= 'Windows':
        command = f"ping -c {count} {hostname}"
    else:
        command = f"ping -n {count} {hostname}"

    try:
        result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return result.returncode
    except subprocess.CalledProcessError as e:
        return e.returncode
    except Exception as e:
        raise
```

