import subprocess

def find_process(process_name):
    try:
        # Validate input: process_name should be a non-empty string
        if not isinstance(process_name, str) or not process_name.strip():
            return "Error: Process name must be a non-empty string"

        # Construct a safe subprocess command
        cmd = ["ps", "-eo", "pid,cmd", "-C", process_name]

        # Run the command and capture output
        output = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        # Check if the command was successful
        if output.returncode!= 0:
            return f"Error running process: {output.stderr.strip()}"

        # Process the output
        output_lines = output.stdout.splitlines()
        if not output_lines:
            return f"No running processes found matching '{process_name}'"
        else:
            return '\n'.join(output_lines)
