import gzip
import os

def compress_file(filepath, output_path=None):
    if not filepath:
        return False

    if not output_path:
        output_path = filepath + '.gz'

    if not shutil.which('gzip'):
        return False

    try:
        with open(filepath, 'rb') as input_file:
            with gzip.open(output_path, 'wb') as output_file:
                shutil.copyfileobj(input_file, output_file)
        return True
    except Exception as e:
        return False
