        raise TypeError("input_path must be a Path or a string")
    if not isinstance(output_path, Path) and not isinstance(output_path, str):
        raise TypeError("output_path must be a Path or a string")
    if not isinstance(width, int) or not isinstance(height, int):
        raise TypeError("width and height must be integers")

    input_path = Path(input_path)
    output_path = Path(output_path)

    if not input_path.exists():
        raise FileNotFoundError(f"The input image '{input_path}' does not exist")

    if input_path.is_dir():
        raise ValueError(f"The input path '{input_path}' is a directory, not a file")

    if input_path.suffix.lower() not in ['.jpg', '.jpeg', '.png', '.gif', '.bmp']:
        raise ValueError(f"Unsupported image format: {input_path.suffix}")

