import subprocess

def clone_repo(repo_url, destination):
    try:
        # Validate input
        if not isinstance(repo_url, str) or not repo_url:
            raise ValueError("Invalid repository URL")
        if not isinstance(destination, str) or not destination:
            raise ValueError("Invalid destination path")

        # Construct git clone command as a list to avoid shell injection
        git_clone_command = ["git", "clone", repo_url, destination]

        # Run the command using subprocess.run
        # Use stdout=subprocess.PIPE and stderr=subprocess.PIPE to capture output
        result = subprocess.run(git_clone_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Check if the command was successful
        if result.returncode == 0:
            return True
        else:
            # Raise an exception with the error message
            raise subprocess.CalledProcessError(result.returncode, git_clone_command, result.stderr.decode('utf-8'))

    except subprocess.CalledProcessError as e:
        # Raise a custom exception with a descriptive error message
        raise GitCloneError(f"Failed to clone repository: {e.stderr.decode('utf-8')}")

class GitCloneError(Exception):
    pass
