    # Split output into lines and filter by process name
    processes = []
    for line in output.splitlines():
        pid, ppid, cmd = line.split()
        if process_name in cmd:
            processes.append(f"{pid} {ppid} {cmd}")

    # Return the list of matching processes as a single string
    return "\n".join(processes)
